package com.srent.booking;
import com.srent.audit.AuditService; import com.srent.common.ApiException; import com.srent.room.*; import com.srent.security.CurrentUser; import com.srent.user.UserRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/bookings") @RequiredArgsConstructor
public class BookingController {
    private final BookingRepository bookings;private final RoomRepository rooms;private final UserRepository users;private final AuditService audit;
    public record Request(@NotNull UUID roomId,@NotNull @FutureOrPresent LocalDate moveInDate,@Size(max=2000)String note){} public record Response(UUID id,UUID roomId,String roomTitle,UUID studentId,UUID landlordId,LocalDate moveInDate,String note,Booking.Status status,Instant createdAt){static Response from(Booking b){return new Response(b.getId(),b.getRoom().getId(),b.getRoom().getTitle(),b.getStudent().getId(),b.getLandlord().getId(),b.getMoveInDate(),b.getNote(),b.getStatus(),b.getCreatedAt());}}
    @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('STUDENT')") @Transactional public Response create(@Valid @RequestBody Request q){var r=rooms.findByIdForUpdate(q.roomId()).orElseThrow(()->ApiException.notFound("Phòng"));if(r.getApprovalStatus()!=Room.ApprovalStatus.APPROVED||r.getStatus()!=Room.Status.AVAILABLE)throw ApiException.conflict("ROOM_NOT_AVAILABLE","Phòng không sẵn sàng để đặt");if(bookings.existsByRoomIdAndStudentIdAndStatus(r.getId(),CurrentUser.id(),Booking.Status.PENDING))throw ApiException.conflict("DUPLICATE_BOOKING","Bạn đã có yêu cầu đang chờ cho phòng này");var b=new Booking();b.setRoom(r);b.setStudent(users.getReferenceById(CurrentUser.id()));b.setLandlord(r.getProperty().getOwner());b.setMoveInDate(q.moveInDate());b.setNote(q.note());bookings.save(b);audit.log(CurrentUser.id(),"BOOKING_CREATED","BOOKING",b.getId(),null);return Response.from(b);}
    @GetMapping("/my") @PreAuthorize("hasRole('STUDENT')") public Page<Response> mine(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return bookings.findAllByStudentId(CurrentUser.id(),p).map(Response::from);}
    @GetMapping("/landlord") @PreAuthorize("hasRole('LANDLORD')") public Page<Response> landlord(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return bookings.findAllByLandlordId(CurrentUser.id(),p).map(Response::from);}
    @PatchMapping("/{id}/accept") @PreAuthorize("hasRole('LANDLORD')") @Transactional public Response accept(@PathVariable UUID id){var b=ownedLandlord(id);var r=rooms.findByIdForUpdate(b.getRoom().getId()).orElseThrow();if(b.getStatus()!=Booking.Status.PENDING||r.getStatus()!=Room.Status.AVAILABLE)throw ApiException.conflict("BOOKING_CONFLICT","Booking hoặc phòng không còn hợp lệ");b.setStatus(Booking.Status.ACCEPTED);r.setStatus(Room.Status.RESERVED);bookings.otherPending(r.getId(),b.getId()).forEach(x->x.setStatus(Booking.Status.REJECTED));audit.log(CurrentUser.id(),"BOOKING_ACCEPTED","BOOKING",b.getId(),null);return Response.from(b);}
    @PatchMapping("/{id}/reject") @PreAuthorize("hasRole('LANDLORD')") @Transactional public Response reject(@PathVariable UUID id){var b=ownedLandlord(id);if(b.getStatus()!=Booking.Status.PENDING)throw ApiException.conflict("INVALID_BOOKING_STATE","Chỉ booking PENDING có thể từ chối");b.setStatus(Booking.Status.REJECTED);audit.log(CurrentUser.id(),"BOOKING_REJECTED","BOOKING",id,null);return Response.from(b);}
    @PatchMapping("/{id}/cancel") @PreAuthorize("hasRole('STUDENT')") @Transactional public Response cancel(@PathVariable UUID id){var b=bookings.findById(id).orElseThrow(()->ApiException.notFound("Booking"));if(!b.getStudent().getId().equals(CurrentUser.id()))throw ApiException.forbidden("Booking không thuộc bạn");if(b.getStatus()!=Booking.Status.PENDING&&b.getStatus()!=Booking.Status.ACCEPTED)throw ApiException.conflict("INVALID_BOOKING_STATE","Không thể hủy booking ở trạng thái này");if(b.getStatus()==Booking.Status.ACCEPTED){var r=rooms.findByIdForUpdate(b.getRoom().getId()).orElseThrow();r.setStatus(Room.Status.AVAILABLE);}b.setStatus(Booking.Status.CANCELLED);audit.log(CurrentUser.id(),"BOOKING_CANCELLED","BOOKING",id,null);return Response.from(b);}
    private Booking ownedLandlord(UUID id){var b=bookings.findById(id).orElseThrow(()->ApiException.notFound("Booking"));if(!b.getLandlord().getId().equals(CurrentUser.id()))throw ApiException.forbidden("Booking không thuộc khu trọ của bạn");return b;}
}
